 boolean ar(){return"ar".equals(lang);} String t(String a,String e){return ar()?a:e;} String bidi(String x){if(x==null||!ar())return x;StringBuilder o=new StringBuilder();boolean latin=false;for(int i=0;i<x.length();i++){char ch=x.charAt(i);boolean l=(ch<128)&&((ch>="A".charAt(0)&&ch<="Z".charAt(0))||(ch>="a".charAt(0)&&ch<="z".charAt(0))||(ch>="0".charAt(0)&&ch<="9")||".:/_-@+#%".indexOf(ch)>=0);if(l&&!latin)o.append("\u2066");if(!l&&latin)o.append("\u2069");o.append(ch);latin=l;}if(latin)o.append("\u2069");return o.toString();} String taskName(){if(!ar())return task;if(task.equals("General"))return"عام";if(task.equals("Marketing"))return"تسويق";if(task.equals("Image prompt"))return"برومبت صورة";if(task.equals("Video prompt"))return"برومبت فيديو";if(task.equals("Voice / TTS"))return"صوت / TTS";if(task.equals("Coding"))return"برمجة";if(task.equals("Research"))return"بحث";if(task.equals("Education"))return"تعليم";if(task.equals("Social media"))return"سوشيال ميديا";if(task.equals("Business"))return"أعمال";return task;} String taskLabel(){return t("المهمة: ","Task: ")+taskName();}
