 LinearLayout root(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(22,18,22,22);l.setBackgroundColor(BG);l.setLayoutDirection(ar()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);final int pl=l.getPaddingLeft(),pt=l.getPaddingTop(),pr=l.getPaddingRight(),pb=l.getPaddingBottom();l.setOnApplyWindowInsetsListener((v,in)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets z=in.getInsets(android.view.WindowInsets.Type.systemBars());v.setPadding(pl+z.left,pt+z.top,pr+z.right,pb+z.bottom);}else{v.setPadding(pl+in.getSystemWindowInsetLeft(),pt+in.getSystemWindowInsetTop(),pr+in.getSystemWindowInsetRight(),pb+in.getSystemWindowInsetBottom());}return in;});return l;}
