 void taskDialog(Button target){String[] en={"General","Marketing","Image prompt","Video prompt","Voice / TTS","Coding","Research","Education","Social media","Business"};String[] arx={"عام","تسويق","برومبت صورة","برومبت فيديو","صوت / TTS","برمجة","بحث","تعليم","سوشيال ميديا","أعمال"};String[] show=ar()?arx:en;new AlertDialog.Builder(this).setTitle(t("اختر نوع المهمة","Choose task")).setItems(show,(d,w)->{task=en[w];target.setText(t("المهمة: ","Task: ")+taskName());}).show();}
 void generate(String idea){if(!s.consume()){toast(t("وصلت للحد المجاني اليومي. افتح Premium.","Daily free limit reached. Upgrade to Premium."));premium();return;}String base=s.get("backend_url","").trim();if(!base.isEmpty()){toast(t("جار التوليد...","Generating..."));new RemotePromptClient().generate(base,idea,sel,task,lang,(ok,val)->runOnUiThread(()->{if(ok){last=val;s.add("history",val);result();}else{local(idea);}}));}else local(idea);}
